                "ADD": 2, "SUB": 2, "EQ": 2, "LT": 2, "LE": 2, "NOT": 1,
                "AND": 2, "OR": 2, "BRANCH": 1, "ALLOC": 1, "FREE": 1,
                "HALT": 1}.get(name, 0)
        if len(stack) < need:
            return finish("PROGRAM_ERROR", op, detail="operand underflow")
